insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('a469afef-6319-478a-b896-cbd88dc8ccb7', 'f18048eb-864a-4511-961d-586feb2d594b', $$inleiding — katalysator en stikstofoxiden$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-palladiumvanger-context1.png$$,
   $$De uitlaat van een auto die op benzine rijdt, bevat een katalysator. Deze katalysator vermindert de uitstoot van schadelijke stoffen zoals koolstofmono-oxide en stikstofoxiden. Stikstofoxiden (NOₓ) veroorzaken milieuvervuiling, doordat ze ongewenste effecten hebben op de kwaliteit van lucht, water en/of bodem.$$, 'inline'),
  ('3ef5b33e-13dc-42ff-995d-d757c584838b', 'f18048eb-864a-4511-961d-586feb2d594b', $$ontleding van stikstofmono-oxide$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-palladiumvanger-context2.png$$,
   $$Een reactie die in de katalysator van een auto optreedt, is de ontleding van stikstofmono-oxide tot stikstof en zuurstof.$$, 'inline'),
  ('4bb4c749-2f55-411a-8e85-a735da278167', 'f18048eb-864a-4511-961d-586feb2d594b', $$eiwit-cellulose-complex bindt palladiumionen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-palladiumvanger-context3.png$$,
   $$Onderzoekers hebben een manier gevonden om op laboratoriumschaal palladiumionen uit een oplossing te verwijderen. Ze maken gebruik van eiwitmoleculen die op een specifieke manier palladiumionen binden. De eiwitmoleculen worden eerst aan cellulosemoleculen gebonden. Hierbij ontstaat een zogenoemd eiwit-cellulose-complex. De binding van de eiwitmoleculen aan de cellulosemoleculen is voornamelijk het gevolg van de vorming van waterstofbruggen. Een fragment van een cellulosemolecuul is hieronder afgebeeld.$$, 'inline'),
  ('919db707-bb07-4e54-98c7-a0a99415d21a', 'f18048eb-864a-4511-961d-586feb2d594b', $$figuur — fragment van een cellulosemolecuul$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-palladiumvanger-context4.png$$,
   $$figuur: structuurformule van een fragment van een cellulosemolecuul, opgebouwd uit meerdere aan elkaar gekoppelde glucose-eenheden (zesringen) verbonden via zuurstofbruggen, met aan de ringen OH-groepen en CH₂OH-groepen die waterstofbruggen kunnen vormen.$$, 'inline'),
  ('a05f4298-eb23-4fb0-8791-beebc967c575', 'f18048eb-864a-4511-961d-586feb2d594b', $$laboratoriumexperiment — verwijderen van Pd2+-ionen (stap 1-4)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-palladiumvanger-context5.png$$,
   $$Hieronder is het laboratoriumexperiment beschreven waarmee Pd²⁺-ionen uit een oplossing van PdCl₂ kunnen worden verwijderd.
1 Het eiwit-cellulose-complex wordt toegevoegd aan een oplossing van PdCl₂. De Pd²⁺-ionen worden daarbij aan het eiwit-cellulose-complex gebonden.
2 De suspensie die in stap 1 ontstaat, wordt gecentrifugeerd. Het eiwit-cellulose-complex met de daaraan gebonden Pd²⁺-ionen wordt daarbij afgescheiden. De overgebleven oplossing bevat geen Pd²⁺-ionen meer.
3 Aan het eiwit-cellulose-complex met de daaraan gebonden Pd²⁺-ionen wordt een oplossing van thio-ureum toegevoegd. Het mengsel wordt flink geschud. De Pd²⁺-ionen komen daarbij los van het complex.
4 Het mengsel dat in stap 3 is ontstaan, is een suspensie. Deze suspensie wordt gecentrifugeerd. Het eiwit-cellulose-complex wordt daarbij gescheiden van de oplossing.$$, 'inline'),
  ('f85090c6-65c7-4093-80d9-2d9ec6bf5198', 'f18048eb-864a-4511-961d-586feb2d594b', $$maximale hoeveelheid Pd2+ per gram eiwit$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-palladiumvanger-context6.png$$,
   $$Per gram eiwit kan maximaal 175 mg Pd²⁺-ionen worden gebonden.$$, 'inline'),
  ('0d054484-d9d0-4a49-b21e-7217da724484', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$figuur 1 — beschrijving battolyser$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context1.png$$,
   $$De battolyser is schematisch weergegeven in figuur 1. De battolyser bestaat uit twee ruimtes die gescheiden zijn door een membraan. Het membraan is doorlaatbaar voor hydroxide-ionen. De ruimtes zijn gevuld met een zeer basische oplossing van kaliumhydroxide en bevatten elk een elektrode. Elke ruimte bevat ook een buis waardoor een gas wordt afgevoerd en een buis waardoor water kan worden aangevuld.$$, 'inline'),
  ('c0947d5f-f199-4ded-bacf-1216da26e256', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$figuur 1 — schema van de battolyser$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context2.png$$,
   $$figuur 1: schema van de battolyser. Twee ruimtes, gescheiden door een membraan (stippellijn), bevatten elk een elektrode (elektrode A links, elektrode B rechts) in een basische kaliumhydroxide-oplossing. Bovenaan verlaat bij elke elektrode een buis met gas de opstelling; onderaan komt bij elke ruimte een buis met water binnen.$$, 'inline'),
  ('3bc3e4a2-53f1-4c7c-a0e1-f2c7979f20cc', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$Energieopslag — reactie 1$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context3.png$$,
   $$Energieopslag
Wanneer de batterij wordt opgeladen, wordt energie opgeslagen. Het proces dat hierbij plaatsvindt, kan met de volgende vergelijking worden weergegeven (reactie 1):
Fe(OH)₂ (s) + 2 Ni(OH)₂ (s) → Fe (s) + 2 NiO(OH) (s) + 2 H₂O (l)$$, 'inline'),
  ('27acde1c-80fc-412c-9b5e-6112caf0a022', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$bindingstypen in NiO(OH)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context4.png$$,
   $$NiO(OH) kan beschouwd worden als opgebouwd uit nikkelionen, oxide-ionen en hydroxide-ionen. In NiO(OH) komen twee bindingstypen voor.$$, 'inline'),
  ('0cb20f3a-3e27-4d2d-9e5c-9b0da486b2da', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$energiediagram reactie 1 nog onvolledig$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context5.png$$,
   $$Op de uitwerkbijlage is het energiediagram van reactie 1 nog onvolledig weergegeven. In dit energiediagram ontbreken het niveau van de geactiveerde toestand en het niveau van de reactieproducten.$$, 'inline'),
  ('8cec5432-53cb-4e25-bb6d-ac622649b079', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$uitwerkbijlage vraag 9 en 10 — leeg energiediagram$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context6.png$$,
   $$leeg energiediagram op de uitwerkbijlage bij vraag 9 en 10: verticale energie-as met alleen het niveau van de beginstoffen ingetekend; de niveaus van de geactiveerde toestand en van de reactieproducten ontbreken nog en moeten worden aangevuld met bijschriften.$$, 'uitwerkbijlage'),
  ('a82e7b2a-1015-458c-9fe8-ffcdb0fea29b', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$halfreacties elektrolyse van water (energieopslag)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context7.png$$,
   $$IJzer en NiO(OH), die ontstaan tijdens het opladen van de batterij, zijn katalysatoren voor de elektrolyse van water. Daardoor wordt in de battolyser, wanneer de batterij al voor een deel opgeladen is, netto water omgezet volgens de volgende halfreacties:
elektrode A: 2 H₂O + 2 e⁻ → H₂ + 2 OH⁻
elektrode B: 4 OH⁻ → O₂ + 2 H₂O + 4 e⁻
De gevormde waterstof kan vervolgens worden gebruikt als (grondstof voor) brandstof.$$, 'inline'),
  ('50d27026-c397-4cd3-91ba-100834719466', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$1,41 kg water omgezet in anderhalf jaar$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context8.png$$,
   $$De eerste battolyser werd anderhalf jaar lang getest. In totaal werd in deze periode 1,41 kg water omgezet.$$, 'inline'),
  ('0d257253-484c-4349-9420-0bfa37b2beda', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$Energielevering — halfreacties$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context9.png$$,
   $$Energielevering
Wanneer meer elektrische energie nodig is dan met behulp van zon of wind wordt opgewekt, kan de battolyser deze energie leveren. Tijdens dit proces treden de volgende halfreacties op:
elektrode A: Fe + 2 OH⁻ → Fe(OH)₂ + 2 e⁻
elektrode B: NiO(OH) + H₂O + e⁻ → Ni(OH)₂ + OH⁻$$, 'inline'),
  ('2715f484-e2ac-467c-8e34-9726f150bfd7', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$uitwerkbijlage — battolyser zonder stroomdraad$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context10.png$$,
   $$Op de uitwerkbijlage is de battolyser nogmaals schematisch weergegeven. In deze figuur ontbreekt een stroomdraad.$$, 'inline'),
  ('7ac5bd0d-19ba-4afe-ae10-971d1c383b8e', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$uitwerkbijlage vraag 13 — battolyser zonder stroomdraad$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context11.png$$,
   $$figuur op de uitwerkbijlage bij vraag 13: hetzelfde schema van de battolyser (twee ruimtes met membraan, elektrode A en elektrode B, gas- en waterbuizen) maar zonder stroomdraad tussen de elektrodes; de stroomdraad en de bewegingsrichting van elektronen en hydroxide-ionen moeten worden ingetekend.$$, 'uitwerkbijlage'),
  ('2db7d16f-92d9-47dd-a7dd-5a59f81478a7', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$TU Delft-model — productie en vraag naar duurzame energie$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context12.png$$,
   $$Aan de TU Delft is een model ontwikkeld waarmee de productie van energie uit zon en wind en de vraag naar duurzaam opgewekte energie zijn geschat. In figuur 2 is een van deze schattingen in een diagram weergegeven. In het diagram zijn het verloop van de gemiddelde hoeveelheid geproduceerde energie en de gemiddelde vraag naar deze energie in 2050 opgenomen.$$, 'inline'),
  ('0665a34f-1939-4ed6-b2d9-da92b04151e5', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$figuur 2 — energieproductie en -vraag per maand$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context13.png$$,
   $$figuur 2: grafiek van de gemiddelde hoeveelheid energie (EJ/dag) tegen de maand van het jaar, voor 2050. Twee lijnen: de vraag naar duurzame energie (doorgetrokken lijn, vrij constant rond 0,7 EJ/dag met een lichte dip in het voorjaar) en de productie van duurzame energie (stippellijn, met een piek van ongeveer 0,9 EJ/dag rond april-juni en lagere waarden rond 0,45-0,5 EJ/dag in de wintermaanden). April en juni zijn in de grafiek gearceerd.$$, 'inline'),
  ('b2c4556a-dad3-4741-8457-c165a6de54d5', '53d02cfa-ecca-4c5e-bde5-1db7aeb27c27', $$schaalvergroting battolyser — van stoeptegel naar zeecontainer$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-battolyser-context14.png$$,
   $$De eerste battolyser had de grootte van een stoeptegel. Bij het vervolgonderzoek krijgt de nieuwe battolyser de grootte van een zeecontainer. Door deze schaalvergroting nemen de risico''s toe die samenhangen met het gebruik van de battolyser.$$, 'inline'),
  ('b0f4492a-cc2f-43b8-b21a-9d1b327b78ab', '58d23a12-9d3b-49e3-aef1-376227309395', $$inleiding — loodvergiftiging door zelfgemaakte wijn$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-lood-in-wijn-context1.png$$,
   $$In 2001 beschreven artsen in Australië een wijnmaker met chronische loodvergiftiging door het drinken van zelfgemaakte wijn. De wijn bleek 14 mg Pb²⁺ per liter te bevatten. Door elke dag van deze wijn te drinken, had de man de aanvaardbare dagelijkse inname (ADI) van het element lood overschreden.$$, 'inline'),
  ('332501e9-31df-4d8d-995d-3ced93a0fbab', '58d23a12-9d3b-49e3-aef1-376227309395', $$oude metalen badkuip met email$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-lood-in-wijn-context2.png$$,
   $$De wijnmaker had een oude metalen badkuip gebruikt om geplette druiven, waaruit de wijn werd gemaakt, een week te bewaren. Deze badkuip was bedekt met een dun laagje email, een hard materiaal dat het metaal beschermde tegen corrosie. Dit email bevat loodzouten en reageert met zuur.$$, 'inline'),
  ('7c346b6b-6eb9-4c8b-854f-7c8a7e23caec', '58d23a12-9d3b-49e3-aef1-376227309395', $$vergelijking wijnmaker/onderzoekers — pH en volume$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-lood-in-wijn-context3.png$$,
   $$Onderzoekers lieten een kleine hoeveelheid email van de badkuip reageren met verdund zuur. Na de reactie werden in het gevormde mengsel Pb²⁺-ionen aangetoond. Om te bepalen of Pb²⁺-ionen uit de badkuip konden vrijkomen tijdens het maken van wijn, deden de onderzoekers commercieel verkrijgbare wijn in de badkuip. Ze bewaarden deze wijn ook een week in de badkuip, waarna de wijn een veel hogere concentratie Pb²⁺-ionen bleek te bevatten dan die van de wijnmaker: maar liefst 310 mg per liter.
Dit verschil in de concentratie Pb²⁺-ionen kan verklaard worden door:
− het verschil in pH van de beide wijnsoorten (oorzaak I)
− het verschil in het gebruikte volume wijn (oorzaak II)
De wijnmaker had ongeveer 100 L wijn gemaakt met pH = 3,8. De onderzoekers gebruikten 4 L wijn met pH = 3,4.$$, 'inline'),
  ('ed2ac2ed-c95d-429c-bf8d-a616cab1118a', '58d23a12-9d3b-49e3-aef1-376227309395', $$figuur 1 — badkuip met 4 L en 100 L wijn$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-lood-in-wijn-context4.png$$,
   $$figuur 1: twee tekeningen van dezelfde badkuip, gevuld met respectievelijk 4 L wijn (laag vloeistofniveau) en 100 L wijn (hoog vloeistofniveau), ter illustratie van het verschil in bedekt email-oppervlak/vloeistofvolume tussen de twee experimenten.$$, 'inline'),
  ('3922c895-6f6d-4448-9465-569d55e81c20', '58d23a12-9d3b-49e3-aef1-376227309395', $$sapa en loodsuiker$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-lood-in-wijn-context5.png$$,
   $$Eeuwen geleden kwam loodvergiftiging door het drinken van wijn vaak voor. De oorzaak was echter een andere dan het gebruik van een oude badkuip. De Oude Romeinen voegden bijvoorbeeld ''sapa'' aan wijn toe. Sapa werkt als conserveermiddel en geeft de wijn een zoetere smaak. De sapa werd gemaakt door druivensap in te koken in loden ketels. Daarbij ontstaat als gevolg van een redoxreactie een oplossing van loodsuiker (Pb(CH₃COO)₂).$$, 'inline'),
  ('751a2100-4bb2-418a-8a13-bee1b43fa0df', '58d23a12-9d3b-49e3-aef1-376227309395', $$test van Gockel$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-lood-in-wijn-context6.png$$,
   $$Al in de 17e eeuw toonde de Duitse arts Eberhard Gockel aan dat er een verband bestaat tussen hevige darmkrampen en het drinken van wijn die Pb²⁺-ionen bevat. Hij ontwikkelde een test om de Pb²⁺-ionen aan te tonen. Hierbij wordt geconcentreerd zwavelzuur druppelsgewijs toegevoegd aan een beetje heldere wijn. Als de wijn meer dan 4,8·10⁻⁵ mol Pb²⁺-ionen per liter bevat, wordt het ontstaan van lood(II)sulfaat (PbSO₄) zichtbaar.$$, 'inline'),
  ('7638e4fc-6490-464b-af84-046477e14be7', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$inleiding — natriumdodecylsulfaat$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context1.png$$,
   $$Om vuile was schoon te krijgen wordt ''wasmiddel'' gebruikt. Bij het wassen van textiel wordt het vuil van het textiel losgemaakt en gemengd met water. Het losgemaakte vuil wordt vervolgens met het water afgevoerd. Wasmiddel is een mengsel van diverse stoffen, waaronder bijvoorbeeld natriumdodecylsulfaat (C₁₂H₂₅SO₄Na). Natriumdodecylsulfaat is oplosbaar in water. Het dodecylsulfaation (C₁₂H₂₅SO₄⁻) heeft een negatief geladen hydrofiel deel dat in water gehydrateerd wordt, en een lange hydrofobe ''staart''. In figuur 1 is het dodecylsulfaation schematisch weergegeven.$$, 'inline'),
  ('d5c0fbbd-acfe-4d57-a54c-88ed05596e12', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$figuur 1 — dodecylsulfaation$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context2.png$$,
   $$figuur 1: schematische structuurformule van het dodecylsulfaation: CH₃−CH₂−CH₂−CH₂−CH₂−CH₂−CH₂−CH₂−CH₂−CH₂−CH₂−CH₂−O−SO₃⁻, met de lange koolwaterstofketen (hydrofobe staart) en de negatief geladen sulfaatgroep (hydrofiele kop) omcirkeld.$$, 'inline'),
  ('9f4b1918-2bd0-4afa-be8e-94b5c6ed5d71', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$micellen en figuur 2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context3.png$$,
   $$Dodecylsulfaationen vormen in water zogenoemde micellen. Een micel is een samenhangende groep ionen waarin de staarten zo dicht mogelijk bij elkaar geplaatst zijn. Micellen kunnen binden met vuildeeltjes en deze vuildeeltjes insluiten. In figuur 2 is een doorsnede van een micel weergegeven, zonder vuildeeltje (figuur 2a) en met vuildeeltje (figuur 2b).$$, 'inline'),
  ('cb7d4d99-d9d8-476d-be06-9b8da51eb1fb', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$figuur 2 — doorsnede van een micel (2a zonder, 2b met vuildeeltje)$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context4.png$$,
   $$figuur 2: doorsnede van een micel. In 2a bestaat de micel uit dodecylsulfaationen met de hydrofiele koppen (bolletjes) naar buiten gericht in het water en de hydrofobe staarten naar binnen; in 2b bevindt zich in het binnenste van de micel, tussen de hydrofobe staarten, een ingesloten vuildeeltje. Op de uitwerkbijlage zijn de structuurformules weergegeven van twee verschillende vuildeeltjes die kunnen voorkomen in voedsel.$$, 'inline'),
  ('eaf21acc-126a-4b54-82b5-7c3855830849', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$vervolg — welk vuildeeltje wordt gebonden$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context5.png$$,
   $$Slechts een van deze vuildeeltjes zal worden gebonden door micellen die zijn opgebouwd zoals weergegeven in figuur 2.$$, 'inline'),
  ('257a7c91-afd8-4127-9a65-81cba69ac0b9', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$wasmiddel bevat enzymen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context6.png$$,
   $$Wasmiddel bevat ook enzymen die vuildeeltjes kunnen afbreken door middel van hydrolyse.$$, 'inline'),
  ('ebf6a64e-51cf-4331-b07d-fb3b266a54ae', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$lipase, pH en figuur 3$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context7.png$$,
   $$Het enzym lipase hydrolyseert vetten. Lipase moet haar werk kunnen doen onder verschillende omstandigheden (zoals pH en temperatuur) bij het wassen. In figuur 3 is te zien hoe de hydrolyse-activiteit van lipase afhangt van de pH. Lipase heeft een pH-optimum.$$, 'inline'),
  ('3b47d963-d5ef-484e-a5fc-c2dabedb7353', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$figuur 3 — relatieve activiteit lipase tegen pH$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context8.png$$,
   $$figuur 3: grafiek van de relatieve activiteit (%) van lipase tegen de pH (bereik 6-10, met onderbroken as). De activiteit stijgt van ongeveer 88% bij pH ≈ 6 naar een maximum (pH-optimum) van 100% bij pH = 7,5, en daalt daarna tot ongeveer 80% bij pH = 9,5.$$, 'inline'),
  ('01162db3-f283-4569-8540-6de83bc3729f', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$figuur 4 — drie aminozuureenheden in lipase$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context9.png$$,
   $$Bij het afbreken van vetten door lipase spelen onder andere drie verschillende aminozuureenheden een belangrijke rol. In figuur 4 is een fragment van lipase, met daarin deze aminozuureenheden, in structuurformule weergegeven. Een van deze drie aminozuureenheden is in waswater negatief geladen doordat die een H⁺-ion heeft afgestaan. De delen van de peptideketen tussen deze drie aminozuureenheden zijn met een golflijn weergegeven.$$, 'inline'),
  ('0caccb26-2ad8-4d82-835a-51c8802b6ff3', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$figuur 4 — structuurformule fragment lipase met eenheden A, B, C$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context10.png$$,
   $$figuur 4: structuurformule van een fragment van lipase met drie aminozuureenheden aangeduid met A, B en C, verbonden via peptidebindingen (−N(H)−C(H)(zijketen)−C(=O)−). Eenheid A heeft een zijketen −CH₂−OH; eenheid B heeft een zijketen −CH₂−C(=O)−O⁻ (negatief geladen carboxylaatgroep); eenheid C heeft een zijketen met een imidazoolring (−CH₂− verbonden met een vijfring met twee stikstofatomen).$$, 'inline'),
  ('97194edd-bf4d-48a7-8c09-6eb044375046', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$veel meer vetdeeltjes dan lipasedeeltjes$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context11.png$$,
   $$In waswater zijn veel meer vetdeeltjes dan lipasedeeltjes aanwezig. Toch kunnen alle vetdeeltjes worden afgebroken.$$, 'inline'),
  ('5471569d-12b6-4a0d-8540-6deba81f9df2', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$uitwerkbijlage vraag 23 — figuur 1 met ruimte voor watermoleculen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context12.png$$,
   $$figuur 1 (dodecylsulfaation) zoals herhaald op de uitwerkbijlage bij vraag 23, met open ruimte eromheen om twee watermoleculen te tekenen die het ion hydrateren.$$, 'uitwerkbijlage'),
  ('fcdc96f1-adf7-43da-b651-92d72fd921da', 'be30ccc8-fdd9-478c-934b-6e466c33b897', $$uitwerkbijlage vraag 24 en 25 — structuurformules vuildeeltje 1 en 2$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-wasmiddel-verwijdert-vlekken-context13.png$$,
   $$structuurformules op de uitwerkbijlage bij vraag 24 en 25.
vuildeeltje 1: een tripeptide-achtig fragment met zijketens −CH₂−COOH (met vrije carbonzuurgroep), −CH₂−OH, en −CH₂−CH₂−S−CH₃ (methioninezijketen), verbonden via peptidebindingen (−N(H)−C(H)(R)−C(=O)−).
vuildeeltje 2: een triglyceride (vet): H₂C−O−C(=O)−C₁₅H₃₁ en H₂C−O−C(=O)−C₁₇H₃₃ aan de buitenste C-atomen van glycerol, en HC−O−C(=O)−C₁₇H₃₃ aan het middelste C-atoom.$$, 'uitwerkbijlage'),
  ('d13c73fb-f576-41c0-988a-31321cf515fc', '7c9a4329-aa19-427e-acb1-19b8c51666b9', $$inleiding — toner en Fe3O4$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-toner-context1.png$$,
   $$In laserprinters en kopieerapparaten wordt ''toner'' gebruikt om tekst en afbeeldingen op papier te brengen. Toner is een korrelig poeder. De korreltjes toner bevatten een kern van voornamelijk Fe₃O₄ met daaromheen een laagje kunststof.$$, 'inline'),
  ('34350bb7-8923-4da2-886b-99466c1311d0', '7c9a4329-aa19-427e-acb1-19b8c51666b9', $$co-polymeer van methylmethacrylaat en styreen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-toner-context2.png$$,
   $$Het laagje kunststof bestaat voornamelijk uit een co-polymeer dat is opgebouwd uit de monomeren methylmethacrylaat en styreen. De structuurformules van deze monomeren staan hieronder.$$, 'inline'),
  ('911263f9-4c08-4c03-9d51-f32c3a9510ce', '7c9a4329-aa19-427e-acb1-19b8c51666b9', $$structuurformules methylmethacrylaat en styreen$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-toner-context3.png$$,
   $$structuurformules van de monomeren: methylmethacrylaat, CH₃−O−C(=O)−C(CH₃)=CH₂, en styreen, C₆H₅−CH=CH₂.$$, 'inline'),
  ('6df7f264-49dd-4009-aefe-3d64ee0cf464', '7c9a4329-aa19-427e-acb1-19b8c51666b9', $$cartridges en achtergebleven toner$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-toner-context4.png$$,
   $$Toner wordt verkocht in een omhulsel, dat een cartridge wordt genoemd. Per jaar worden naar schatting wereldwijd 1,1 miljard cartridges gevuld met toner verkocht. Van deze hoeveelheid cartridges komen er uiteindelijk 500 miljoen na gebruik op een vuilnisbelt terecht. Een gebruikte cartridge bevat nog een achtergebleven hoeveelheid toner. Het is ongewenst wanneer toner in het milieu terechtkomt.$$, 'inline'),
  ('9011c983-89b7-4a08-b673-dd312d0f5915', '7c9a4329-aa19-427e-acb1-19b8c51666b9', $$cartridges zijn thermoplastisch$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-toner-context5.png$$,
   $$De cartridges zijn veelal gemaakt van een thermoplastische kunststof en kunnen daardoor gemakkelijk gerecycled worden.$$, 'inline'),
  ('fc69acd2-ed4f-4ec1-aba1-5fa08494c092', '7c9a4329-aa19-427e-acb1-19b8c51666b9', $$terugwinnen van ijzer — proces in de oven$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-toner-context6.png$$,
   $$De cartridges zouden gerecycled kunnen worden, maar voor de overgebleven toner is dat lastiger. Australische onderzoekers hebben een proces ontwikkeld waarmee ijzer uit toner kan worden teruggewonnen. Dit gebeurt door het Fe₃O₄ met behulp van het co-polymeer, dat eveneens in toner aanwezig is, om te zetten tot ijzer. Hieronder is beschreven hoe dit proces op kleine schaal wordt uitgevoerd.
De toner wordt samengeperst tot tabletten. Een tablet wordt vervolgens in een oven geplaatst bij een temperatuur van 1550 °C. Door de oven wordt voortdurend argon geleid.
figuur: schema van de ovenopstelling. Argon stroomt aan de linkerkant de oven in, langs een toner-tablet dat op een houder is geplaatst; het ontstane gasmengsel verlaat de oven aan de rechterkant.$$, 'inline'),
  ('d6fa8dbb-6112-480a-989a-5a35a0ca88f8', '7c9a4329-aa19-427e-acb1-19b8c51666b9', $$ontleding van het co-polymeer in de oven$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-toner-context7.png$$,
   $$In de oven ontleedt het co-polymeer tot methaan, koolstofmono-oxide en koolstofdioxide. Het gevormde methaan ontleedt vervolgens tot koolstof en waterstof. Vervolgens wordt ijzer gevormd als gevolg van voornamelijk onderstaande reacties.$$, 'inline'),
  ('5ff79864-9fe8-4ad3-a2eb-3246c633730a', '7c9a4329-aa19-427e-acb1-19b8c51666b9', $$reactie 1, 2 en 3 — vorming van ijzer$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-toner-context8.png$$,
   $$Fe₃O₄ + CO → 3 FeO + CO₂ (reactie 1)
FeO + C → Fe + CO (reactie 2)
FeO + CO → Fe + CO₂ (reactie 3)$$, 'inline'),
  ('bbc78f2e-e8e2-403a-8dbc-c5e92e44793d', '7c9a4329-aa19-427e-acb1-19b8c51666b9', $$argon voert gassen af$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-toner-context9.png$$,
   $$Door voortdurend argon door te leiden worden de ontstane gassen, samen met het argon, uit de oven verwijderd. De onderzoekers kregen zo een product dat grotendeels uit ijzer bestond. Dit ijzer kan gebruikt worden in de staalindustrie.$$, 'inline'),
  ('34be98f8-6ba2-44b0-ada9-907443c17de2', '7c9a4329-aa19-427e-acb1-19b8c51666b9', $$tablet — massa en ijzergehalte$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-toner-context10.png$$,
   $$Voorafgaand aan de behandeling in de oven heeft een tablet een massa van 0,50 g en bevat het 23,9 massaprocent ijzer. Na de behandeling is er 0,098 gram ijzer verkregen.$$, 'inline'),
  ('8c2d4965-330a-4d50-b4c2-c690b1e3b5fc', '7c9a4329-aa19-427e-acb1-19b8c51666b9', $$economisch voordeel van terugwinnen ijzer$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-toner-context11.png$$,
   $$Het terugwinnen van ijzer uit toner is economisch gezien mogelijk voordelig. Er zijn ook andere redenen voor te geven.$$, 'inline');

