  ('225f8ec1-eb0b-4e69-8fe1-a53ac7700f56', 'f18048eb-864a-4511-961d-586feb2d594b', 4,
   '[{"domain": "Materie", "subdomain": "Bindingen en eigenschappen"}]'::jsonb,
   '["waterstofbrug", "atoomgroep", "cellulose", "eiwit", "polaire binding"]'::jsonb,
   $$Aanwijzen van de atoomgroepen die waterstofbruggen vormen tussen cellulose en eiwitten.$$,
   $$https://rfyffbietarhprlbvdek.supabase.co/storage/v1/object/public/practice-question-images/scheikunde-havo-2021-ii-palladiumvanger-vraag4.png$$, $$Geef aan tussen welke atoomgroepen van cellulose en welke atoomgroepen van eiwitten de waterstofbruggen kunnen worden gevormd. Maak eventueel gebruik van Binas-tabel 67H1 of ScienceData-tabel 13.7c.
Noteer je antwoord als volgt:
atoomgroep cellulose: …
atoomgroep eiwit: …$$, array['4bb4c749-2f55-411a-8e85-a735da278167', '919db707-bb07-4e54-98c7-a0a99415d21a']::uuid[]),
  ('452814a2-8958-4489-9471-22785813d850', 'f18048eb-864a-4511-961d-586feb2d594b', 5,
   '[{"domain": "Rekenen en analyse", "subdomain": "Grootheden en relaties"}]'::jsonb,
   '["molverhouding", "molaire massa", "significante cijfers", "eiwit"]'::jsonb,
   $$Berekenen van de molverhouding tussen gebonden Pd2+-ionen en eiwit met behulp van molaire massa''s.$$,
